// OpsServer is the server API for Ops service.
// All implementations must embed UnimplementedOpsServer
// for forward compatibility.
//
// Ops 运维服务契约（S7-01，v4/03 阶段 7 任务正本）。
//
// 职责边界（02 §2.3 唯一写入方）：
//   - ops_db 全部表归本服务：alert_rule / alert / ticket / ticket_log / sla_timer /
//     inspection_plan / inspection_template / inspection_task / inspection_item。
//   - SLA 策略正本在 contract（FR-CTR-007），本服务只做计时（sla_timer 快照冻结）；
//     ListSlaStrategy 为 contract 透传，前端不直连 contract。
//   - 告警判定/聚合归本服务（FR-IOT-009：iotingest 只做候选初筛）；
//     消费 alert_candidate/cmd_failed/ota_paused/device_anomaly/station_created，
//     发出 alert_created + notification_request（Outbox 同事务）。
//   - 派单匹配（区域+技能）调 party.ListStaff 拉候选，匹配逻辑归本服务；
//     设备→场站归属调 station.GetDeviceStation。
//   - 延迟任务不走 MQ（ADR-09）：接单超时/SLA 超时/巡检生成 = next_exec_at 索引 + cron 注册表扫描。
//
// 约定：ID 传输层 int64、对外 string（E8）；时间 UnixMilli；枚举一律 string。
type OpsServer interface {
	Ping(context.Context, *PingReq) (*PingResp, error)
	// ---- 告警规则（FR-OPS-001）----
	CreateAlertRule(context.Context, *CreateAlertRuleReq) (*CreateAlertRuleResp, error)
	UpdateAlertRule(context.Context, *UpdateAlertRuleReq) (*UpdateAlertRuleResp, error)
	DeleteAlertRule(context.Context, *DeleteAlertRuleReq) (*DeleteAlertRuleResp, error)
	ListAlertRule(context.Context, *ListAlertRuleReq) (*ListAlertRuleResp, error)
	// ---- 告警（FR-OPS-002/003/009/010）----
	// ListAlert 全量列表（分页过滤）；PendingAlerts 轮询增量（since_id + Redis 未读计数）。
	ListAlert(context.Context, *ListAlertReq) (*ListAlertResp, error)
	GetAlert(context.Context, *GetAlertReq) (*GetAlertResp, error)
	// AckAlert 确认（OPEN→ACKED，记录确认人）。
	AckAlert(context.Context, *AckAlertReq) (*AckAlertResp, error)
	// TransferAlertToTicket 转工单（隐含确认 OPEN→ACKED；level→优先级；可选自动派单）。
	TransferAlertToTicket(context.Context, *TransferAlertToTicketReq) (*TransferAlertToTicketResp, error)
	// CloseAlert 关闭（前置：closed_ticket_id 已验收工单，或人工备注原因）。
	CloseAlert(context.Context, *CloseAlertReq) (*CloseAlertResp, error)
	// ArchiveAlert 归档（终态，只读留痕）。
	ArchiveAlert(context.Context, *ArchiveAlertReq) (*ArchiveAlertResp, error)
	// PendingAlerts 轮询增量接口（轻量 <5KB / P95<100ms，FR-OPS-010）。
	PendingAlerts(context.Context, *PendingAlertsReq) (*PendingAlertsResp, error)
	// ---- 工单（FR-OPS-004/005/008）----
	// 状态机：PENDING_DISPATCH→DISPATCHED→ACCEPTED→PROCESSING→SUBMITTED→VERIFIED→CLOSED；
	// 任意非终态→CANCELLED。接单超时由 escalate_at 扫描升级（ADR-09，无 MQ 延迟消息）。
	CreateTicket(context.Context, *CreateTicketReq) (*CreateTicketResp, error)
	GetTicket(context.Context, *GetTicketReq) (*GetTicketResp, error)
	ListTicket(context.Context, *ListTicketReq) (*ListTicketResp, error)
	// MatchStaff 派单候选（场站区域 + 技能标签匹配，FR-OPS-004/FR-PTY-005）。
	MatchStaff(context.Context, *MatchStaffReq) (*MatchStaffResp, error)
	// DispatchTicket 派单（assignee_uid 空 = MatchStaff 自动取第一候选）。
	DispatchTicket(context.Context, *DispatchTicketReq) (*DispatchTicketResp, error)
	AcceptTicket(context.Context, *AcceptTicketReq) (*AcceptTicketResp, error)
	StartTicket(context.Context, *StartTicketReq) (*StartTicketResp, error)
	// SubmitTicket 处理完成提交（附结果说明）。
	SubmitTicket(context.Context, *SubmitTicketReq) (*SubmitTicketResp, error)
	// VerifyTicket 验收（pass=false 退回 PROCESSING；告警工单验收后可 CloseAlert）。
	VerifyTicket(context.Context, *VerifyTicketReq) (*VerifyTicketResp, error)
	CloseTicket(context.Context, *CloseTicketReq) (*CloseTicketResp, error)
	CancelTicket(context.Context, *CancelTicketReq) (*CancelTicketResp, error)
	// PendingTickets 轮询增量接口（与 PendingAlerts 同构，FR-OPS-010）。
	PendingTickets(context.Context, *PendingTicketsReq) (*PendingTicketsResp, error)
	// ---- SLA（FR-OPS-006；策略正本 contract，本服务计时）----
	// ListSlaStrategy 透传 contract.ListSlaStrategy（前端管理入口统一走 ops）。
	ListSlaStrategy(context.Context, *ListSlaStrategyReq) (*ListSlaStrategyResp, error)
	// GetSlaTimer 工单计时器详情（策略快照/暂停留痕/分级升级状态）。
	GetSlaTimer(context.Context, *GetSlaTimerReq) (*GetSlaTimerResp, error)
	// PauseSlaTimer 暂停（必填原因，留痕；pause_minutes 累计）。
	PauseSlaTimer(context.Context, *PauseSlaTimerReq) (*PauseSlaTimerResp, error)
	// ResumeSlaTimer 恢复（due_at 顺延累计暂停时长）。
	ResumeSlaTimer(context.Context, *ResumeSlaTimerReq) (*ResumeSlaTimerResp, error)
	// ---- 巡检（FR-OPS-007）----
	// station_created 消费自动建计划（默认模板）；计划 cron 表达式限简化集合：
	// @daily / @weekly / @monthly / @h:N（每 N 小时）。
	CreateInspectionPlan(context.Context, *CreateInspectionPlanReq) (*CreateInspectionPlanResp, error)
	UpdateInspectionPlan(context.Context, *UpdateInspectionPlanReq) (*UpdateInspectionPlanResp, error)
	ListInspectionPlan(context.Context, *ListInspectionPlanReq) (*ListInspectionPlanResp, error)
	CreateInspectionTemplate(context.Context, *CreateInspectionTemplateReq) (*CreateInspectionTemplateResp, error)
	ListInspectionTemplate(context.Context, *ListInspectionTemplateReq) (*ListInspectionTemplateResp, error)
	ListInspectionTask(context.Context, *ListInspectionTaskReq) (*ListInspectionTaskResp, error)
	GetInspectionTask(context.Context, *GetInspectionTaskReq) (*GetInspectionTaskResp, error)
	// SubmitInspectionTask 批量提交明细；异常项（anomalous=true）自动生成工单（type=INSPECTION）。
	SubmitInspectionTask(context.Context, *SubmitInspectionTaskReq) (*SubmitInspectionTaskResp, error)
	mustEmbedUnimplementedOpsServer()
}

